pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 mtFeeRate) public {
        // Ensure mtFeeRate is in valid range
        vm.assume(mtFeeRate <= 1e18);

        // Record base reserve before the call
        uint256 baseReserveBefore = c._BASE_RESERVE_();
        uint256 mtFeeBaseBefore = c._MT_FEE_BASE_();

        // Make the call
        c.adjustMtFeeRate(mtFeeRate);

        // After the call, the sum of baseReserve and mtFeeBase must be <= balance
        // (Since _BASE_RESERVE_ in P is unchanged, but in M it becomes stale)
        uint256 baseReserveAfter = c._BASE_RESERVE_();
        uint256 mtFeeBaseAfter = c._MT_FEE_BASE_();
        uint256 baseBalanceAfter = c._BASE_TOKEN_().balanceOf(address(c));

        // General rule: _BASE_RESERVE_ + _MT_FEE_BASE_ <= total balance (should hold always)
        assertTrue(baseReserveAfter + mtFeeBaseAfter <= baseBalanceAfter);
    }
}

