pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate) public {
        // Bound mtFeeRate to a range that does not immediately revert (max 1e18)
        mtFeeRate = bound(mtFeeRate, 0, 1e18);

        // Record _BASE_RESERVE_ before the call
        (uint256 baseReserveBefore, ) = c.getVaultReserve();

        // Call adjustMtFeeRate (can revert if mtFeeRate > 1e18, but we bounded)
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.adjustMtFeeRate.selector, mtFeeRate));
        if (!ok) {
            // If it reverts, the property is vacuously true (no state change observed)
            assertTrue(true);
            return;
        }

        // After call, _BASE_RESERVE_ must equal the initial base resistor minus zero mt fee base
        (uint256 baseReserveAfter, ) = c.getVaultReserve();
        assertTrue(baseReserveBefore == baseReserveAfter, "_BASE_RESERVE_ should not change");
    }
}

