// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 baseAmount, uint256 quoteAmount, uint256 mtFeeRate, address maintainer) public {
        // Bound the amounts to avoid overflow and ensure valid token balances
        vm.assume(baseAmount > 0 && baseAmount < 1e30);
        vm.assume(quoteAmount > 0 && quoteAmount < 1e30);
        vm.assume(mtFeeRate <= 1e18);
        vm.assume(maintainer != address(0));

        // Mint initial tokens to this contract to simulate deposit
        deal(address(c._BASE_TOKEN_()), address(this), baseAmount);
        deal(address(c._QUOTE_TOKEN_()), address(this), quoteAmount);

        // Approve the contract to spend our tokens (not needed for buyShares since it uses balanceOf)
        // Actually buyShares reads the balance directly, so just transfer tokens to C first
        IERC20 baseToken = IERC20(c._BASE_TOKEN_());
        IERC20 quoteToken = IERC20(c._QUOTE_TOKEN_());
        baseToken.transfer(address(c), baseAmount);
        quoteToken.transfer(address(c), quoteAmount);

        // Buy shares to initialize the pool
        c.buyShares(address(this));

        // Now set maintainer and adjust fee rate to zero
        vm.prank(c._MAINTAINER_());
        c.adjustMtFeeRate(0); // Set mt fee to zero

        // After adjustMtFeeRate, no fee is accumulated so _QUOTE_RESERVE_ should still match the balance
        // But the bug prevents _QUOTE_RESERVE_ from ever updating in _sync
        // To detect the bug, we need a scenario where _sync is called and would update _QUOTE_RESERVE_
        // For example, after a sellShares, _sync is called
        // Let's first withdraw the mt fee (which is zero, so no effect)
        vm.prank(c._MAINTAINER_());
        c.withdrawMtFeeTotal();

        // Now add more quote tokens to the contract to simulate a donation / direct transfer
        deal(address(c._QUOTE_TOKEN_()), address(c), quoteAmount);

        // Now call sync, which calls _sync
        c.sync();

        // The reference implementation would update _QUOTE_RESERVE_ to the actual balance (including donation)
        // The buggy one would never update _QUOTE_RESERVE_
        // So the rule: after sync, _QUOTE_RESERVE_ should equal the actual quote balance minus mt fee quote
        uint256 expectedQuoteReserve = IERC20(c._QUOTE_TOKEN_()).balanceOf(address(c)) - c._MT_FEE_QUOTE_();
        assertTrue(c._QUOTE_RESERVE_() == expectedQuoteReserve, "Quote reserve should match balance after sync");
    }
}

