pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate, address randomUser, uint256 transferAmount) public {
        // Constrain inputs so reference works: mtFeeRate <= 1e18, transferAmount > 0 and not too large
        vm.assume(mtFeeRate <= 1e18);
        vm.assume(transferAmount > 0 && transferAmount < 1e30);
        vm.assume(randomUser != address(0));

        // 1. Set mtFeeRate on the contract
        vm.prank(c._MAINTAINER_());
        c.adjustMtFeeRate(mtFeeRate);

        // 2. Transfer some tokens directly to contract to change quote balance without calling sync
        // We need quote token address; get it from public getter
        address quoteToken = address(c._QUOTE_TOKEN_());
        // Deal tokens to randomUser
        vm.deal(randomUser, 1 ether);
        vm.prank(randomUser);
        (bool success, ) = quoteToken.call{value: transferAmount}("");
        // The quote token is not ETH; we need an ERC20. For simplicity, use a mock or assume it's ETH.
        // Since we don't have a mock, we'll skip this because we need actual token addresses.
        // Instead, use a simpler invariant: after adjustMtFeeRate, the _QUOTE_RESERVE_ should equal
        // the contract's quote token balance minus _MT_FEE_QUOTE_.
        // But that's already tried. So we need a different approach.
        // Given the bug never updates _QUOTE_RESERVE_, a subsequent buyShares will not see the real quote balance,
        // leading to wrong quoteInput computation. So let's test that.

        // Reset: set mtFeeRate to same value again
        vm.prank(c._MAINTAINER_());
        c.adjustMtFeeRate(mtFeeRate);

        // Get quote balance minus mt fee
        uint256 quoteReserveBefore = c._QUOTE_RESERVE_();
        uint256 mtFeeQuoteBefore = c._MT_FEE_QUOTE_();
        uint256 quoteBalance = c._QUOTE_TOKEN_().balanceOf(address(c));
        uint256 expectedQuoteReserve = quoteBalance - mtFeeQuoteBefore;

        // The rule: the _QUOTE_RESERVE_ must equal the actual quote balance minus _MT_FEE_QUOTE_
        // after adjustMtFeeRate call.
        assertTrue(c._QUOTE_RESERVE_() == expectedQuoteReserve, "Quote reserve not updated");
    }
}

