        // But we need a public function that calls _twapUpdate. The only such function is buyShares/sellShares/sync, but they have other requirements.
        // Instead, we can call sync() which does _twapUpdate if _IS_OPEN_TWAP_ is true and reserves nonzero.
        c.sync();
        // Record cumulative price after first update
        uint256 priceCumulative1 = c._BASE_PRICE_CUMULATIVE_LAST_();
        // Advance time
        vm.warp(block.timestamp + 100);
        // Second call to sync
        c.sync();
        uint256 priceCumulative2 = c._BASE_PRICE_CUMULATIVE_LAST_();
        // The general rule: cumulative price should never decrease
        assertTrue(priceCumulative2 >= priceCumulative1);
    }
}

